namespace Challenge;public interface IRemote{Task<string> FetchAsync(string id,CancellationToken ct);}public sealed class Aggregator(IRemote remote,int maxConcurrency=4){public int ConfiguredConcurrency=>maxConcurrency;public Task<IReadOnlyList<string>> FetchAllAsync(IReadOnlyList<string> ids,CancellationToken ct=default){var r=new List<string>();foreach(var id in ids)r.Add(remote.FetchAsync(id,ct).Result);return Task.FromResult<IReadOnlyList<string>>(r);}}
